import { useState } from "react";
export default function Form11() {
  const [forminput, setforminput] = useState({
    name: "",
    email: "",
    age: "",
    enfo: "",
    town: " ",
    job: " ",
  });
  return (
    <>
      <form
        onSubmit={(ev) => {
          ev.preventDefault();
        }}
      >
        <label> name</label>
        <input
          value={forminput.name}
          onChange={(as) => {
            setforminput({ ...forminput, name: as.target.value });
          }}
        />
        <label> email</label>
        <input
          value={forminput.email}
          onChange={(as) => {
            setforminput({ ...forminput, email: as.target.value });
          }}
        />
        <label> age</label>
        <input
          value={forminput.age}
          onChange={(as) => {
            setforminput({ ...forminput, age: as.target.value });
          }}
        />
        <hr></hr>
        <label> inputtext</label>
        <textarea
          value={forminput.enfo}
          onChange={(as) => {
            setforminput({ ...forminput, enfo: as.target.value });
          }}
        />
        <hr></hr>
        <select
          value={forminput.town}
          onChange={(as) => {
            setforminput({ ...forminput, town: as.target.value });
          }}
        >
          <option>ksa</option>
          <option>ps</option>
        </select>
        <hr></hr>
        <div>
          <input
            value={""}
            type="radio"
            name="job"
            checked={forminput.job == "techer"}
            onChange={(as) => {
              setforminput({ ...forminput, town: as.target.value });
            }}
          />
          techer
          <input type="radio" name="job" checked={forminput.job == "student"} />
          student
        </div>
        <hr></hr>
        <button>sumbet</button>
      </form>
    </>
  );
}
